SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0880000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 88, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "88", "printedPageNumber": 88, "pdfPageNumber": 471, "sequenceIndex": 78, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0880100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0880000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "their deterioration?\" One of Hadhrat Abu Darda''s (Radhiyallaho anho) pupils says \"After hearing this hadith from Hadhrat Abu Darda (Radhiyallaho anho), I went to Hadhrat Ubaadah (Radhiyallaho anho) and related the hadith to him.\" He said, \"Abu Darda (Radhiyallaho anho) is quite right. May I tell you the first thing that will be taken away from this world? It is devotion in salaat. You will see that not a single person in the full congregation is saying his salaat with devotion.\" Hadhrat Huzaifah (Radhiyallaho anho), the confidante of the Prophet (Sallallaho alaihe wasallam), was also heard saying, \"Devotion in salaat shall be the first thing to disappear.\"\n\nIt is said in a hadith, \"Allah does not pay any attention to that salaat with which ruku and sajdah are not performed properly.\"\n\nAnother hadith says, \"A person has been offering salaat for sixty years, but in fact not a single salaat of his is accepted by Allah. This is because he has been careless about his ruku in some salaats and about his sajdah in others.\"\n\nA great stress is laid on the proper performance of salaat in the famous Epistles of Shaikh Ahmad Sirhindi (Rahmatullah alaih). His discourses on the subject cover a good portion of the Epistles. In one of them he writes, \"It is necessary among other things that, we should be particular about keeping the fingers of our hands together while in sajdah and separated while in ruku. These regulations are not without a purpose.\" He further writes, \"To keep our glance at the place of sajdah while standing, on our feet while in ruku, on our nose while in sajdah, and on our hands while in Qa''dah, goes a long way in keeping the desired concentration in salaat.\" When such ordinary regulations, which are only mustahab, increase the value of our salaat, you can well imagine how much benefit we shall derive if we be particular of other regulations, which are either sunnat or otherwise more important.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880200-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880300-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أُمِّ رُومَانَ رَضِيَ اللَّهُ عَنْهَا وَالِدَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ رَآنِي أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ أَتَمَيَّلُ فِي صَلَاتِي فَزَجَرَنِي زَجْرَةً كِدْتُ أَنْصَرِفُ مِنْ صَلَاتِي قَالَ سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ إِذَا قَامَ أَحَدُكُمْ فِي الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}]}'::jsonb);